    17	    private static final BigDecimal TAXA = new BigDecimal("0.0199");
    19	    public String codigo() {
    20	        return "CARTAO";
    21	    }
    23	    public void validarParcelas(int parcelas) {
    24	        if (parcelas < 1 || parcelas > MAX_PARCELAS) {
    25	            throw new ErroNegocio(CodigoErro.PARCELAMENTO_INVALIDO);
    26	        }
    27	    }
    29	    public Cobranca cobrar(BigDecimal total, int parcelas, boolean comCupom) {
    30	        if (parcelas <= MAX_SEM_JUROS) {
    31	            BigDecimal parcela = Dinheiro.arredondar(total.divide(BigDecimal.valueOf(parcelas), MathContext.DECIMAL128));
    32	            return new Cobranca(total, parcela);
    33	        }
    35	        BigDecimal f = BigDecimal.ONE.add(TAXA).pow(parcelas);
    36	        BigDecimal parcela = Dinheiro.arredondar(
    37	                total.multiply(TAXA).multiply(f).divide(f.subtract(BigDecimal.ONE), MathContext.DECIMAL128));
    38	        return new Cobranca(Dinheiro.arredondar(parcela.multiply(BigDecimal.valueOf(parcelas))), parcela);
    39	    }
