    56	    private static <T> Map<String, T> indexar(List<T> lista, Function<T, String> chave) {
    57	        Map<String, T> mapa = new LinkedHashMap<>();
    58	        lista.forEach(e -> mapa.put(chave.apply(e), e));
    59	        return mapa;
    60	    }
    62	    public Resumo calcular(CompraRequest r) {
    64	        validarBasico(r);
    65	        List<String> skus = r.itens().stream().map(CompraRequest.ItemDados::sku).toList();
    66	        Map<String, Produto> catalogo = produtos.buscarPorSkus(skus);
    67	        if (!catalogo.keySet().containsAll(skus)) {
    68	            throw new ErroNegocio(CodigoErro.PRODUTO_INEXISTENTE);
    69	        }
    70	        if (catalogo.values().stream().anyMatch(Produto::foraDeLinha)) {
    71	            throw new ErroNegocio(CodigoErro.PRODUTO_FORA_DE_LINHA);
    72	        }
    73	        List<LinhaItem> linhas = new ArrayList<>();
    74	        for (CompraRequest.ItemDados item : r.itens()) {
    75	            Produto p = catalogo.get(item.sku());
    76	            if (item.quantidade() > p.estoque()) {
    77	                throw new ErroNegocio(CodigoErro.ESTOQUE_INSUFICIENTE);
    78	            }
    79	            linhas.add(new LinhaItem(p, item.quantidade()));
    80	        }
    83	        NivelClube nivel = r.nivelClube() == null ? null : niveis.get(r.nivelClube());
    84	        if (nivel == null) {
    85	            throw new ErroNegocio(CodigoErro.NIVEL_CLUBE_INVALIDO);
    86	        }
    87	        Regiao regiao = Regiao.de(r.regiao());
    88	        if (regiao == null) {
    89	            throw new ErroNegocio(CodigoErro.REGIAO_INVALIDA);
    90	        }
    91	        if (r.cep() == null || !CEP.matcher(r.cep()).matches()) {
    92	            throw new ErroNegocio(CodigoErro.CEP_INVALIDO);
    93	        }
    96	        ModalidadeEntrega modalidade = r.modalidadeEntrega() == null ? null : modalidades.get(r.modalidadeEntrega());
    97	        if (modalidade == null) {
    98	            throw new ErroNegocio(CodigoErro.MODALIDADE_INVALIDA);
    99	        }
   100	        BigDecimal subtotal = linhas.stream().map(LinhaItem::total).reduce(Dinheiro.ZERO, BigDecimal::add);
   101	        BigDecimal peso = linhas.stream()
   102	                .map(l -> l.produto().pesoKg().multiply(BigDecimal.valueOf(l.quantidade())))
   103	                .reduce(BigDecimal.ZERO, BigDecimal::add);
   104	        Cotacao cotacao = modalidade.cotar(new PedidoEntrega(r.cep(), regiao, peso));
   105	        BigDecimal frete = nivel.isentaFrete() && modalidade.permiteIsencaoFrete() ? Dinheiro.ZERO : cotacao.frete();
   108	        BigDecimal desconto = Dinheiro.ZERO;
   109	        if (r.cupom() != null) {
   110	            Cupom cupom = cupons.get(r.cupom());
   111	            if (cupom == null) {
   112	                throw new ErroNegocio(CodigoErro.CUPOM_INVALIDO);
   113	            }
   114	            BigDecimal bruto = cupom.desconto(new ContextoCupom(r.cliente().cpf(), linhas, subtotal, modalidade, frete));
   115	            desconto = Dinheiro.minimo(Dinheiro.arredondar(bruto), Dinheiro.fracao(subtotal, TETO_DESCONTO));
   116	        }
   118	        BigDecimal seguro = regiao.seguro(subtotal);
   119	        BigDecimal total = subtotal.subtract(desconto).add(frete).add(seguro);
   122	        FormaPagamento forma = r.formaPagamento() == null ? null : formasPagamento.get(r.formaPagamento());
   123	        if (forma == null) {
   124	            throw new ErroNegocio(CodigoErro.FORMA_PAGAMENTO_INVALIDA);
   125	        }
   126	        int parcelas = r.parcelas() == null ? 1 : r.parcelas();
   127	        forma.validarParcelas(parcelas);
   128	        forma.validarDisponibilidade(total);
   129	        Cobranca cobranca = forma.cobrar(total, parcelas, r.cupom() != null);
   131	        return new Resumo(
   132	                subtotal,
   133	                desconto,
   134	                frete,
   135	                cotacao.prazoDias(),
   136	                seguro,
   137	                cobranca.totalFinal().subtract(total),
   138	                cobranca.totalFinal(),
   139	                parcelas,
   140	                cobranca.valorParcela(),
   141	                Dinheiro.fracao(subtotal, nivel.fracaoCredito()),
   142	                nivel.brinde(subtotal));
   143	    }
   145	    private void validarBasico(CompraRequest r) {
   146	        if (r == null || r.cliente() == null || r.itens() == null || r.itens().isEmpty()) {
   147	            throw new ErroNegocio(CodigoErro.PEDIDO_INVALIDO);
   148	        }
   149	        Set<String> vistos = new HashSet<>();
   150	        for (CompraRequest.ItemDados item : r.itens()) {
   151	            if (item == null || item.sku() == null || item.sku().isBlank() || !vistos.add(item.sku())
   152	                    || item.quantidade() == null || item.quantidade() <= 0) {
   153	                throw new ErroNegocio(CodigoErro.PEDIDO_INVALIDO);
   154	            }
   155	        }
   156	        String cpf = r.cliente().cpf();
   157	        String email = r.cliente().email();
   158	        if (cpf == null || !CPF.matcher(cpf).matches() || email == null || email.isBlank()) {
   159	            throw new ErroNegocio(CodigoErro.PEDIDO_INVALIDO);
   160	        }
   161	    }
